         const float* x = reinterpret_cast<const float*>(x_in);
+        // Integer exponent-field check (== isfinite) instead of std::isfinite:
+        // on RISC-V std::isfinite lowers to fabs+frflags+fle+fsflags around
+        // every element, serializing the FP pipeline via FCSR reads/writes.
+        // Testing `(bits & 0x7f800000) != 0x7f800000` is pure-integer and
